(function (w, d) {
    var cfg = w.TTT_PRODUCT_SHOW || {};
    var PRODUCT_ID = cfg.productId;
    var HAS_VARIANTS = !!cfg.hasVariants;
    var CSRF = cfg.csrf || (d.querySelector('meta[name="csrf-token"]') || {}).content;
    var VARIANTS = cfg.variants || [];
    var SIZES = cfg.sizes || [];
    var COLOR_IMAGES = cfg.colorImages || {};
    var COLOR_URLS = cfg.colorUrls || {};
    var galleryImages = cfg.galleryImages || [];
    var frontImages = cfg.frontImages || [];
    var backImages = cfg.backImages || [];
    var bothImages = cfg.bothImages || cfg.allImages || galleryImages;
    var allImages = cfg.allImages || galleryImages;
    var galleryIndex = 0;
    var selectedSize = null;
    var selectedColor = cfg.selectedColor || '';
    var selectedQty = 1;
    var selectedDesignSide = cfg.defaultDesignSide || (cfg.availablePrintSides === 'front_only' ? 'front' : (cfg.availablePrintSides === 'back_only' ? 'back' : null));
    var lastCart = null;

    function byId(id) { return d.getElementById(id); }
    function qsa(sel) { return Array.prototype.slice.call(d.querySelectorAll(sel)); }
    function setText(id, text) { var el = byId(id); if (el) el.textContent = text; }
    function csrfToken() {
        var meta = d.querySelector('meta[name="csrf-token"]');
        CSRF = (w.tttCsrfToken ? w.tttCsrfToken() : (meta ? meta.content : CSRF || cfg.csrf || ''));
        cfg.csrf = CSRF;
        return CSRF;
    }
    function money(value) { return '₹' + Math.round(Number(value || 0)).toLocaleString('en-IN'); }

    function activeVariant(size, color) {
        return VARIANTS.find(function (v) {
            return (!size || v.size === size) && (!color || v.color === color);
        }) || null;
    }

    function updatePriceDisplay(variant) {
        var price = Number((variant && variant.price) || cfg.basePrice || 0);
        var mrp = Number((variant && variant.original_price) || cfg.baseOriginalPrice || 0);
        var hasDiscount = mrp > price;
        setText('displayPrice', money(price));
        setText('displayMrp', money(mrp));
        var mrpWrap = byId('displayMrpWrap');
        var discount = byId('displayDiscount');
        if (mrpWrap) mrpWrap.style.display = hasDiscount ? '' : 'none';
        if (discount) {
            discount.style.display = hasDiscount ? '' : 'none';
            discount.textContent = hasDiscount ? ('Save ' + Math.round(((mrp - price) / mrp) * 100) + '%') : '';
        }
        if (cfg.drawerProduct) {
            cfg.drawerProduct.price = price;
            cfg.drawerProduct.original_price = hasDiscount ? mrp : price;
        }
    }

    function escapeHtml(str) {
        if (!str) return '';
        return String(str)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#039;');
    }

    function normalizeImages(images) {
        return (images || []).map(function (img) {
            if (typeof img === 'string') {
                return { url: img, side: 'all' };
            }
            return img;
        }).filter(function (img) {
            return img && img.url;
        });
    }

    function updateHeroImage(img) {
        var main = byId('mainImg');
        var url = (typeof img === 'string') ? img : (img && img.url ? img.url : '');
        if (main && url) {
            main.src = url;
        }
        var badge = byId('mainImgSideBadge');
        if (badge) {
            var side = img && img.side ? img.side : (url && /back|rear|reverse/i.test(url) ? 'back' : null);
            if (side === 'front' || side === 'back') {
                badge.textContent = (side === 'front' ? 'Front' : 'Back') + ' View';
                badge.style.display = '';
            } else {
                badge.style.display = 'none';
            }
        }
    }

    function render2ColGrid(imgs) {
        var grid = byId('gallery2ColGrid');
        if (!grid) return;
        var subImgs = (imgs || []).slice(1);
        if (!subImgs.length) {
            grid.style.display = 'none';
            grid.innerHTML = '';
            return;
        }
        grid.style.display = 'grid';
        grid.innerHTML = subImgs.map(function (img, idx) {
            var sideBadge = '';
            if (img.side === 'front') {
                sideBadge = '<span class="gallery-side-badge">Front</span>';
            } else if (img.side === 'back') {
                sideBadge = '<span class="gallery-side-badge">Back</span>';
            }
            var safeUrl = escapeHtml(img.url);
            var safeName = escapeHtml(cfg.drawerProduct && cfg.drawerProduct.name ? cfg.drawerProduct.name : 'Product');
            return '<div class="pd-gallery-sub-card" onclick="openProductGallery(' + (idx + 1) + ')" data-side="' + escapeHtml(img.side || 'all') + '">' +
                '<img src="' + safeUrl + '" alt="' + safeName + '" loading="lazy" onerror="this.src=\'/images/placeholder-product.jpg\'">' +
                sideBadge +
                '</div>';
        }).join('');
    }

    function switchImg(url, thumb, index) {
        var main = byId('mainImg');
        if (main) main.src = url;
        if (typeof index === 'number') galleryIndex = index;
        qsa('.pd-thumb').forEach(function (t) { t.classList.remove('active'); });
        if (thumb) thumb.classList.add('active');
    }

    function renderLightboxThumbs() {
        var wrap = byId('productLightboxThumbs');
        if (!wrap) return;
        wrap.innerHTML = galleryImages.map(function (img, i) {
            return '<button type="button" class="' + (i === galleryIndex ? 'active' : '') + '" onclick="showProductGalleryImage(' + i + ')">' +
                '<img src="' + escapeHtml(img.url) + '" alt="">' +
                '</button>';
        }).join('');
    }

    function showProductGalleryImage(index) {
        galleryImages = normalizeImages(galleryImages);
        if (!galleryImages.length) return;
        galleryIndex = (Number(index) + galleryImages.length) % galleryImages.length;
        var img = byId('productLightboxImg');
        var count = byId('productLightboxCount');
        if (img) img.src = galleryImages[galleryIndex].url;
        if (count) count.textContent = (galleryIndex + 1) + ' / ' + galleryImages.length;
        renderLightboxThumbs();
    }

    function openProductGallery(index) {
        galleryImages = normalizeImages(galleryImages.length ? galleryImages : cfg.galleryImages);
        if (!galleryImages.length) return;
        var pop = byId('productLightbox');
        if (!pop) return;
        pop.classList.add('is-open');
        pop.setAttribute('aria-hidden', 'false');
        d.body.style.overflow = 'hidden';
        showProductGalleryImage(typeof index === 'number' ? index : galleryIndex);
    }

    function closeProductGallery() {
        var pop = byId('productLightbox');
        if (pop) {
            pop.classList.remove('is-open');
            pop.setAttribute('aria-hidden', 'true');
            d.body.style.overflow = '';
        }
    }

    function moveProductGallery(delta) {
        showProductGalleryImage(galleryIndex + Number(delta || 0));
    }

    function findColorItem(color) {
        if (!color) return null;
        var target = String(color).toLowerCase();
        return qsa('.color-item').find(function (el) {
            return String(el.getAttribute('data-color') || '').toLowerCase() === target;
        }) || null;
    }

    function updateColorUrl(color, replace) {
        if (!color || !w.history) return;
        var item = findColorItem(color);
        var next = COLOR_URLS[color] || (item && item.dataset ? item.dataset.url : '');
        if (!next && w.URL) {
            var url = new URL(w.location.href);
            url.searchParams.set('color', color);
            next = url.pathname + url.search + url.hash;
        }
        if (!next || next === w.location.pathname + w.location.search + w.location.hash) return;
        (replace ? w.history.replaceState : w.history.pushState).call(w.history, { color: color }, '', next);
    }

    function getColorFromUrl() {
        try { return new URL(w.location.href).searchParams.get('color') || ''; }
        catch (e) { return ''; }
    }

    function updateSizesForColor(color) {
        qsa('.size-btn').forEach(function (btn) {
            var size = btn.getAttribute('data-size');
            var matches = VARIANTS.filter(function (v) { return v.color === color && v.size === size; });
            var hasStock = matches.some(function (v) { return Number(v.stock) > 0; });
            btn.classList.toggle('oos', !hasStock);
            btn.disabled = !hasStock;
        });
    }

    function rebuildThumbs(imgs) {
        var thumbs = byId('thumbsContainer');
        if (!thumbs) return;
        thumbs.innerHTML = '';
        imgs.forEach(function (img, i) {
            var wrap = d.createElement('div');
            var image = d.createElement('img');
            wrap.className = 'pd-thumb' + (i === 0 ? ' active' : '');
            wrap.onclick = function () { switchImg(img.url, wrap, i); };
            wrap.ondblclick = function () { openProductGallery(i); };
            image.src = img.url;
            image.alt = '';
            image.onerror = function () { image.style.display = 'none'; };
            wrap.appendChild(image);
            thumbs.appendChild(wrap);
        });
    }

    function selectColor(color, hex, el, skipUrl) {
        selectedColor = color;
        selectedSize = null;
        qsa('.color-item').forEach(function (c) { c.classList.remove('active'); });
        if (el) el.classList.add('active');
        setText('selectedColorLabel', color);
        var imgs = COLOR_IMAGES[color] || COLOR_IMAGES.all || [];
        if (imgs.length > 0) {
            galleryImages = normalizeImages(imgs);
            galleryIndex = 0;
            var main = byId('mainImg');
            if (main) main.src = imgs[0].url;
            rebuildThumbs(imgs);
        }
        updateSizesForColor(color);
        var firstValidBtn = qsa('.size-btn:not(.oos):not([disabled])')[0];
        if (firstValidBtn) {
            selectSize(firstValidBtn);
        } else {
            selectedSize = null;
            setText('selSize', 'Select');
            var sel = byId('selSize');
            if (sel) sel.style.color = '#ff3f6c';
            qsa('.size-btn').forEach(function (b) { b.classList.remove('active'); });
            var atc = byId('atcBtn');
            if (atc) {
                atc.textContent = 'SELECT SIZE';
                atc.style.background = '';
                atc.disabled = false;
            }
        }
        if (!skipUrl) updateColorUrl(color, false);
    }

    function selectSize(btn) {
        if (!btn || btn.classList.contains('oos') || btn.disabled) return;
        qsa('.size-btn').forEach(function (b) { b.classList.remove('active'); });
        btn.classList.add('active');
        selectedSize = btn.getAttribute('data-size');
        setText('selSize', selectedSize);
        var sel = byId('selSize');
        if (sel) sel.style.color = '#1a1a1a';
        var v = activeVariant(selectedSize, selectedColor);
        var msg = byId('variantMsg');
        if (v && msg) {
            if (Number(v.stock) <= 0) msg.textContent = 'Out of stock';
            else if (Number(v.stock) <= 5) msg.textContent = 'Only ' + v.stock + ' left!';
            else msg.textContent = 'In stock (' + v.stock + ' available)';
        }
        updatePriceDisplay(v);
        var atc = byId('atcBtn');
        if (atc) {
            atc.textContent = 'ADD TO CART';
            atc.style.background = '';
            atc.disabled = false;
        }
    }

    function selectDesignSide(side, btn) {
        selectedDesignSide = side || null;
        qsa('.pd-side-btn').forEach(function (b) { b.classList.remove('active'); });
        if (btn) {
            btn.classList.add('active');
        } else if (selectedDesignSide) {
            var matchingBtn = qsa('.pd-side-btn').find(function (b) {
                return b.getAttribute('data-side') === selectedDesignSide;
            });
            if (matchingBtn) matchingBtn.classList.add('active');
        }

        var box = byId('designSideBox');
        var msg = byId('designSideMsg');
        if (box) box.classList.remove('needs-choice');
        if (msg) msg.style.display = 'none';

        var label = byId('selDesignSideLabel');
        if (label) {
            if (selectedDesignSide === 'front') {
                label.textContent = 'Front Side';
                label.style.color = '#00285a';
            } else if (selectedDesignSide === 'back') {
                label.textContent = 'Back Side';
                label.style.color = '#00285a';
            } else {
                label.textContent = 'Please Select';
                label.style.color = '#ef4444';
            }
        }

        var confirmBadge = byId('sideConfirmBadge');
        var confirmText = byId('sideConfirmText');
        if (confirmBadge) {
            if (selectedDesignSide === 'front' || selectedDesignSide === 'back') {
                confirmBadge.style.display = 'flex';
                if (confirmText) confirmText.textContent = selectedDesignSide === 'back' ? 'BACK' : 'FRONT';
            } else {
                confirmBadge.style.display = 'none';
            }
        }

        var frontList = (frontImages && frontImages.length) ? frontImages.slice() : (cfg.frontImage ? [{ url: cfg.frontImage, side: 'front' }] : []);
        var backList = (backImages && backImages.length) ? backImages.slice() : (cfg.backImage ? [{ url: cfg.backImage, side: 'back' }] : []);
        var bothList = (bothImages && bothImages.length) ? bothImages.slice() : (allImages && allImages.length ? allImages.slice() : galleryImages.slice());

        var activeList = [];
        if (selectedDesignSide === 'front') {
            activeList = frontList.slice();
            if (!activeList.length) {
                activeList = (allImages || []).filter(function (img) { return img && img.side === 'front'; });
            }
            if (!activeList.length && bothList.length) {
                activeList = [bothList[0]];
            }
        } else if (selectedDesignSide === 'back') {
            activeList = backList.slice();
            if (!activeList.length) {
                activeList = (allImages || []).filter(function (img) { return img && img.side === 'back'; });
            }
            if (!activeList.length) {
                var backMatch = (allImages || []).find(function (img) {
                    return img && img.url && /back|rear|reverse/i.test(img.url);
                });
                if (backMatch) {
                    activeList = [backMatch];
                } else if (bothList.length > 1) {
                    activeList = [bothList[1]];
                }
            }
        } else {
            // 'both' mode: display both front and back
            activeList = bothList.slice();
        }

        if (!activeList.length) {
            activeList = (galleryImages && galleryImages.length ? galleryImages : (allImages || [])).slice();
        }

        galleryImages = normalizeImages(activeList);
        galleryIndex = 0;

        if (galleryImages.length > 0) {
            updateHeroImage(galleryImages[0]);
            render2ColGrid(galleryImages);
            rebuildThumbs(galleryImages);
            renderLightboxThumbs();
        }
    }

    function cartPayload(isBuyNow) {
        return {
            product_id: PRODUCT_ID,
            size: selectedSize,
            color: selectedColor || null,
            design_side: selectedDesignSide || null,
            quantity: selectedQty,
            buy_now: !!isBuyNow,
            set_quantity: !!isBuyNow
        };
    }

    function changeQty(delta) {
        selectedQty = Math.max(1, Math.min(10, selectedQty + Number(delta || 0)));
        setText('qtyVal', selectedQty);
    }

    function addToCart(openPopup, buttonId, onSuccess) {
        var btn = byId(buttonId || 'atcBtn');
        var size = selectedSize;
        var isBuyNow = buttonId === 'buyBtn';
        var defaultBtnText = isBuyNow ? 'BUY IT NOW' : (openPopup ? 'BUY IT NOW' : 'ADD TO CART');
        if (!btn) return Promise.resolve(null);
        if (HAS_VARIANTS && qsa('.size-btn').length > 0 && !size) {
            btn.textContent = 'SELECT SIZE FIRST!';
            btn.style.background = '#f97316';
            setTimeout(function () {
                btn.style.background = '';
                btn.textContent = isBuyNow ? 'BUY IT NOW' : (openPopup ? 'BUY IT NOW' : 'SELECT SIZE');
            }, 1500);
            return Promise.resolve(null);
        }

        if (!selectedDesignSide) {
            var sideBox = byId('designSideBox');
            var sideMsg = byId('designSideMsg');
            if (sideBox) {
                sideBox.classList.remove('needs-choice');
                void sideBox.offsetWidth;
                sideBox.classList.add('needs-choice');
                sideBox.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
            if (sideMsg) {
                sideMsg.style.display = 'block';
                sideMsg.textContent = '⚠️ Please select Front Side or Back Side print first!';
            }
            btn.textContent = 'SELECT PRINT SIDE!';
            btn.style.background = '#dc2626';
            btn.style.color = '#ffffff';
            setTimeout(function () {
                btn.style.background = '';
                btn.style.color = '';
                btn.textContent = defaultBtnText;
            }, 1800);
            showToast('Please select Front Side or Back Side print.');
            return Promise.resolve(null);
        }

        if (window.TTT_IS_AUTHENTICATED === false) {
            if (w.TTT_AUTH_MODAL && typeof w.TTT_AUTH_MODAL.open === 'function') {
                w.TTT_AUTH_MODAL.open(function () {
                    window.TTT_IS_AUTHENTICATED = true;
                    addToCart(openPopup, buttonId, onSuccess);
                });
                return Promise.resolve(null);
            }
        }

        btn.textContent = openPopup ? 'Opening...' : 'Adding...';
        btn.disabled = true;
        return fetch(cfg.cartAddUrl, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': csrfToken(), 'Accept': 'application/json' },
            body: JSON.stringify(cartPayload(isBuyNow))
        }).then(function (r) { return r.json(); })
            .then(function (res) {
                if (res.success) {
                    if (!openPopup) {
                        btn.textContent = 'Added!';
                        btn.classList.add('adding');
                        showToast('Added to cart!');
                    }
                    var badge = byId('cart-count');
                    if (badge && (res.count || res.cart_count)) badge.textContent = res.count || res.cart_count;
                    if (typeof onSuccess === 'function') onSuccess(res);
                    else if (openPopup) openCheckoutPop(res.cart);
                    setTimeout(function () {
                        btn.textContent = defaultBtnText;
                        btn.classList.remove('adding');
                        btn.disabled = false;
                    }, openPopup ? 300 : 1600);
                } else if (w.TTT_AUTH_MODAL && w.TTT_AUTH_MODAL.needsAuth(res)) {
                    btn.textContent = defaultBtnText;
                    btn.disabled = false;
                    w.TTT_AUTH_MODAL.open(function () { addToCart(openPopup, buttonId, onSuccess); });
                } else {
                    btn.textContent = res.message || 'Error';
                    btn.disabled = false;
                }
                return res;
            }).catch(function () {
                btn.textContent = defaultBtnText;
                btn.disabled = false;
                return null;
            });
    }

    function fallbackCart() {
        var p = cfg.drawerProduct || {};
        var price = Number(p.price || cfg.basePrice || 0);
        return {
            count: 1,
            subtotal: price,
            shipping: price >= 999 ? 0 : 50,
            discount: 0,
            savings: Math.max(0, Number(p.original_price || price) - price),
            total: price + (price >= 999 ? 0 : 50),
            items: [{ name: p.name || 'Product', image: p.image || '', price: price, original_price: Number(p.original_price || price), quantity: selectedQty, size: selectedSize, color: selectedColor, design_side: selectedDesignSide }]
        };
    }

    function openCheckoutPop(cart) {
        cart = cart || fallbackCart();
        lastCart = cart;
        var items = cart.items || [];
        var count = items.reduce(function(sum, it){ return sum + Number(it.quantity || 1); }, 0);
        var subtotal = items.reduce(function(sum, it){ return sum + (Number(it.price || 0) * Number(it.quantity || 1)); }, 0);
        var totalMrp = items.reduce(function(sum, it){
            var price = Number(it.price || 0);
            var orig = it.original_price && Number(it.original_price) > price ? Number(it.original_price) : price;
            return sum + (orig * Number(it.quantity || 1));
        }, 0);
        var savingsOnMrp = Math.max(0, totalMrp - subtotal);
        var prepaidSave = Math.round(subtotal * 0.05 * 100) / 100;
        var shipping = subtotal >= 999 ? 0 : 50;
        var couponDisc = Number(cart.discount || 0);
        var finalTotal = Math.max(0, subtotal + shipping - prepaidSave - couponDisc);
        var totalSavings = savingsOnMrp + prepaidSave + couponDisc;
        var discPct = totalMrp > subtotal ? Math.round(((totalMrp - subtotal) / totalMrp) * 100) : 0;

        // Milestone calculation
        var milestoneFillPct = 0;
        var milestoneText = '';
        if (subtotal < 500) {
            milestoneFillPct = (subtotal / 500) * 15;
            milestoneText = 'Add items worth <b>' + money(500 - subtotal) + '</b> more to unlock <b>10% off</b> with code <b>FIRST10</b>';
        } else if (subtotal < 5999) {
            milestoneFillPct = 15 + ((subtotal - 500) / (5999 - 500)) * 45;
            milestoneText = 'Add items worth <b>' + money(5999 - subtotal) + '</b> more to unlock <b>15% off</b> with code <b>GOBONKERS15</b>';
        } else if (subtotal < 9999) {
            milestoneFillPct = 60 + ((subtotal - 5999) / (9999 - 5999)) * 40;
            milestoneText = 'Add items worth <b>' + money(9999 - subtotal) + '</b> more to unlock <b>20% off</b> with code <b>MEGA20</b>';
        } else {
            milestoneFillPct = 100;
            milestoneText = '🎉 <b>Maximum 20% Discount Unlocked!</b> Use code <b>MEGA20</b>';
        }

        var mFill = byId('coMilestoneFill');
        if (mFill) mFill.style.width = Math.min(100, Math.max(5, milestoneFillPct)) + '%';
        var mText = byId('coMilestoneText');
        if (mText) mText.innerHTML = milestoneText;

        var n1 = byId('node1');
        var n2 = byId('node2');
        var n3 = byId('node3');
        if (n1) n1.className = subtotal >= 500 ? 'milestone-node active' : 'milestone-node';
        if (n2) n2.className = subtotal >= 5999 ? 'milestone-node active' : 'milestone-node';
        if (n3) n3.className = subtotal >= 9999 ? 'milestone-node active' : 'milestone-node';

        setText('coCartCount', count);
        setText('coFloatingSaved', money(totalSavings) + ' Saved so far!');
        setText('coStickyMrp', money(totalMrp));
        setText('coStickyTotal', money(finalTotal));
        setText('coStickyDiscountPct', discPct > 0 ? '(' + discPct + '% OFF)' : '');
        setText('coPrepaidSaveText', 'Save up to ' + money(prepaidSave) + ' on Prepaid');
        setText('coCartSubtotal', money(subtotal));
        setText('coSavingsMrp', '-' + money(savingsOnMrp));
        setText('coShipping', shipping === 0 ? 'FREE' : money(shipping));

        var promoBlack = byId('coPromoBlack');
        var milestonesCard = byId('coMilestonesCard');
        var couponCard = byId('cartSlideCouponCard');
        var crosssell = byId('cartSlideCrosssell');
        var footerWrap = byId('coFooterWrap');

        if (count === 0 || items.length === 0) {
            if (promoBlack) promoBlack.style.display = 'none';
            if (milestonesCard) milestonesCard.style.display = 'none';
            if (couponCard) couponCard.style.display = 'none';
            if (crosssell) crosssell.style.display = 'none';
            if (footerWrap) footerWrap.style.display = 'none';
        } else {
            if (promoBlack) promoBlack.style.display = 'block';
            if (milestonesCard) milestonesCard.style.display = 'block';
            if (couponCard) couponCard.style.display = 'block';
            if (crosssell) crosssell.style.display = 'block';
            if (footerWrap) footerWrap.style.display = 'block';
        }

        if (typeof w.switchToSlideCartView === 'function') {
            w.switchToSlideCartView();
        }
        renderOrderItems(cart);
        var pop = byId('checkoutPop');
        if (pop) {
            pop.classList.add('is-open');
            pop.setAttribute('aria-hidden', 'false');
            d.body.style.overflow = 'hidden';
        }
    }

    function closeCheckoutPop() {
        var pop = byId('checkoutPop');
        if (pop) {
            pop.classList.remove('is-open');
            pop.setAttribute('aria-hidden', 'true');
        }
        d.body.style.overflow = '';
    }

    w.removeDrawerItem = function(index) {
        if (!lastCart || !lastCart.items || !lastCart.items[index]) return;
        var item = lastCart.items[index];
        var itemName = item.name || 'Item';
        if (item.key && cfg.cartUpdateBaseUrl) {
            var removeUrl = cfg.cartUpdateBaseUrl.replace('/update', '/remove') + '/' + encodeURIComponent(item.key);
            fetch(removeUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': csrfToken(), 'Accept': 'application/json' },
                body: JSON.stringify({ _method: 'DELETE' })
            }).catch(function() {});
        }
        lastCart.items.splice(index, 1);
        recalcDrawerCart();
        var badge = byId('cart-count');
        if (badge) badge.textContent = lastCart.items.reduce(function(sum, it){ return sum + Number(it.quantity || 1); }, 0);
        if (typeof w.tttNotify === 'function') {
            w.tttNotify('"' + itemName + '" removed from cart.', 'info');
        } else if (typeof toastr !== 'undefined') {
            toastr.info('"' + itemName + '" removed from cart.');
        }
    };

    function renderOrderItems(cart) {
        var wrap = byId('coOrderItems');
        if (!wrap) return;
        var items = cart.items || [];
        if (items.length === 0) {
            wrap.innerHTML = '<div class="cart-slide-empty-state">' +
                '<div class="empty-icon-circle"><i class="bi bi-bag-x"></i></div>' +
                '<h4 class="empty-title">Your bag is empty</h4>' +
                '<p class="empty-sub">Explore our signature streetwear drops and add your favorites!</p>' +
                '<a href="/shop" class="btn-cart-slide-checkout btn-empty-shop"><span>START SHOPPING</span> <i class="bi bi-arrow-right"></i></a>' +
                '</div>';
            return;
        }

        var sizes = SIZES.length ? SIZES.slice() : VARIANTS.map(function (v) { return v.size; });
        sizes = sizes.filter(Boolean).filter(function (value, index, arr) { return arr.indexOf(value) === index; });

        wrap.innerHTML = items.map(function (item, index) {
            var qty = Number(item.quantity || 1);
            var price = Number(item.price || 0);
            var itemSizes = sizes.slice();
            if (item.size && itemSizes.indexOf(item.size) === -1) itemSizes.unshift(item.size);
            if (!itemSizes.length) itemSizes = [item.size || 'Free Size'];
            var options = itemSizes.map(function (size) {
                return '<option value="' + escapeHtml(size) + '"' + (size === item.size ? ' selected' : '') + '>' + escapeHtml(size) + '</option>';
            }).join('');
            var origPrice = item.original_price && Number(item.original_price) > price ? Number(item.original_price) : price;
            var disc = origPrice > price ? Math.round(((origPrice - price) / origPrice) * 100) : 0;

            return '<div class="cart-slide-item" data-cart-index="' + index + '">' +
                '<div class="cart-item-thumb-box">' +
                    '<img src="' + (item.image || '/images/placeholder-product.jpg') + '" alt="' + escapeHtml(item.name || 'Product') + '" onerror="this.src=\'/images/placeholder-product.jpg\'">' +
                '</div>' +
                '<div class="cart-item-details">' +
                    '<div class="cart-item-row-top">' +
                        '<span class="cart-item-name" title="' + escapeHtml(item.name || 'Product') + '">' + escapeHtml(item.name || 'Product') + '</span>' +
                        (origPrice > price ? '<span class="cart-item-mrp-price">' + money(origPrice * qty) + '</span>' : '') +
                    '</div>' +
                    '<div class="cart-item-row-mid">' +
                        '<select class="cart-size-pill-select" onchange="changeDrawerSize(' + index + ', this.value)">' + options + '</select>' +
                        (item.design_side ? '<span style="font-size:10px;font-weight:800;background:#eff6ff;color:#1d4ed8;padding:2px 7px;border-radius:4px;border:1px solid #bfdbfe;margin-left:4px;white-space:nowrap;">Print: ' + escapeHtml(item.design_side.toUpperCase()) + '</span>' : '') +
                        '<div class="cart-item-selling-side">' +
                            '<strong class="cart-item-cur-price">' + money(price * qty) + '</strong>' +
                            (disc > 0 ? '<span class="cart-item-disc-green">(' + disc + '% OFF)</span>' : '') +
                        '</div>' +
                    '</div>' +
                    '<div class="cart-item-row-bottom">' +
                        '<div class="cart-qty-stepper-pill">' +
                            '<button type="button" onclick="changeDrawerQty(' + index + ',-1)" aria-label="Decrease">−</button>' +
                            '<span>' + qty + '</span>' +
                            '<button type="button" onclick="changeDrawerQty(' + index + ',1)" aria-label="Increase">+</button>' +
                        '</div>' +
                        '<button type="button" class="btn-cart-item-trash" onclick="removeDrawerItem(' + index + ')" title="Remove item"><i class="bi bi-trash3"></i></button>' +
                    '</div>' +
                '</div>' +
            '</div>';
        }).join('');
    }

    w.toggleSlideBreakdown = function() {
        var el = byId('coStickyBreakdown');
        var ch = byId('coBreakdownChevron');
        if (!el) return;
        if (el.style.display === 'none' || !el.style.display) {
            el.style.display = 'flex';
            if (ch) ch.style.transform = 'rotate(180deg)';
        } else {
            el.style.display = 'none';
            if (ch) ch.style.transform = 'rotate(0deg)';
        }
    };

    w.openCouponsInSlideDrawer = function() {
        var cartView = byId('coSlideCartView');
        var offersView = byId('coSlideOffersView');
        if (cartView) cartView.style.display = 'none';
        if (offersView) offersView.style.display = 'flex';
        renderSlideOffers();
    };

    w.switchToSlideCartView = function() {
        var cartView = byId('coSlideCartView');
        var offersView = byId('coSlideOffersView');
        if (offersView) offersView.style.display = 'none';
        if (cartView) cartView.style.display = 'flex';
    };

    w.switchOfferTab = function(tab) {
        var tabBrand = byId('tabBrandOffers');
        var tabPayment = byId('tabPaymentOffers');
        var contentBrand = byId('contentBrandOffers');
        var contentPayment = byId('contentPaymentOffers');

        if (tab === 'payment') {
            if (tabBrand) tabBrand.className = 'slide-offer-tab';
            if (tabPayment) tabPayment.className = 'slide-offer-tab active';
            if (contentBrand) contentBrand.style.display = 'none';
            if (contentPayment) contentPayment.style.display = 'block';
        } else {
            if (tabBrand) tabBrand.className = 'slide-offer-tab active';
            if (tabPayment) tabPayment.className = 'slide-offer-tab';
            if (contentBrand) contentBrand.style.display = 'block';
            if (contentPayment) contentPayment.style.display = 'none';
        }
    };

    function currentDrawerTotals() {
        var items = lastCart && lastCart.items ? lastCart.items : [];
        return {
            count: items.reduce(function(sum, it){ return sum + Number(it.quantity || 1); }, 0),
            subtotal: items.reduce(function(sum, it){
                return sum + (Number(it.price || 0) * Number(it.quantity || 1));
            }, 0)
        };
    }

    function isPercentCoupon(coupon) {
        var type = String(coupon.type || '').toLowerCase();
        return type === 'percent' || type === 'percentage';
    }

    function couponCategory(coupon) {
        if (coupon.category) return coupon.category;
        return String(coupon.code || '').toUpperCase() === 'PREPAID5' ? 'payment' : 'brand';
    }

    function computeCouponSaving(coupon, subtotal) {
        if (typeof coupon.saving !== 'undefined') return Math.round(Number(coupon.saving || 0));
        var value = Number(coupon.value || 0);
        var saving = isPercentCoupon(coupon) ? (subtotal * value / 100) : Math.min(subtotal, value);
        if (coupon.max_discount && Number(coupon.max_discount) > 0) {
            saving = Math.min(saving, Number(coupon.max_discount));
        }
        return Math.round(Math.max(0, saving));
    }

    function couponUnlockText(coupon, minSpend) {
        if (coupon.unlock_text) return coupon.unlock_text;
        var valueText = isPercentCoupon(coupon)
            ? Math.round(Number(coupon.value || 0)) + '% off'
            : money(coupon.value || 0) + ' off';
        return 'Add items worth ' + money(minSpend) + ' to unlock ' + valueText + ' with code ' + coupon.code;
    }

    function offerIconSvg() {
        return '<span class="offer-flower-icon">' +
            '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#10b981" stroke-width="2"><path d="M12 2l2.4 2.4 3.4-.6 1.2 3.2 3.2 1.2-.6 3.4 2.4 2.4-2.4 2.4.6 3.4-3.2 1.2-1.2 3.2-3.4-.6-2.4 2.4-2.4-2.4-3.4.6-1.2-3.2-3.2-1.2.6-3.4-2.4-2.4 2.4-2.4-.6-3.4 3.2-1.2 1.2-3.2 3.4.6 2.4-2.4z"/></svg>' +
            '</span>';
    }

    function renderAvailableOffer(item, appliedCode) {
        var code = escapeHtml(item.code || '');
        var isApplied = appliedCode && String(appliedCode).toUpperCase() === String(item.code || '').toUpperCase();
        return '<div class="slide-offer-item-row">' +
            '<div class="offer-row-top">' +
                '<div class="offer-code-badge-wrap">' +
                    offerIconSvg() +
                    '<span class="offer-dashed-pill">' + code + '</span>' +
                '</div>' +
                '<button type="button" class="offer-apply-btn" onclick="applySpecificCoupon(\'' + code + '\')">' + (isApplied ? 'Applied' : 'Apply') + '</button>' +
            '</div>' +
            '<div class="offer-saving-line">You save ' + money(item.discount || 0) + '</div>' +
            '<div class="offer-terms-line">' + escapeHtml(item.desc || 'Applicable on Prepaid & COD orders. T&C Apply') + '</div>' +
        '</div>';
    }

    function renderUnavailableOffer(item) {
        return '<div class="slide-offer-item-row">' +
            '<div class="offer-row-top">' +
                '<div class="offer-code-badge-wrap">' +
                    offerIconSvg() +
                    '<span class="offer-dashed-pill">' + escapeHtml(item.code || '') + '</span>' +
                '</div>' +
                '<button type="button" class="offer-add-items-link" onclick="switchToSlideCartView()">+ Add Item(s)</button>' +
            '</div>' +
            '<div class="offer-warning-line">Add item worth ' + money(item.needed || 0) + ' amount more to avail</div>' +
            '<div class="offer-terms-line">' + escapeHtml(item.desc || '') + '</div>' +
        '</div>';
    }

    function renderSlideOfferData(coupons, subtotal, count, appliedCode) {
        setText('coOffersCartCount', count);

        var brandAvailable = [];
        var brandUnavailable = [];
        var paymentOffers = [];

        (coupons || []).forEach(function(c) {
            var minSpend = Number(c.min_spend || 0);
            var eligible = typeof c.is_eligible === 'boolean' ? c.is_eligible : subtotal >= minSpend;
            var row = {
                code: c.code,
                discount: computeCouponSaving(c, subtotal),
                needed: Math.round(Number(c.shortage || Math.max(0, minSpend - subtotal))),
                desc: eligible ? (c.description || 'Applicable on Prepaid & COD orders. T&C Apply') : couponUnlockText(c, minSpend)
            };

            if (couponCategory(c) === 'payment') {
                paymentOffers.push(Object.assign({}, row, { eligible: eligible }));
            } else if (eligible) {
                brandAvailable.push(row);
            } else {
                brandUnavailable.push(row);
            }
        });

        var availEl = byId('coAvailableOffersList');
        if (availEl) {
            availEl.innerHTML = brandAvailable.length
                ? brandAvailable.map(function(item) { return renderAvailableOffer(item, appliedCode); }).join('')
                : '<div style="font-size: 12px; color: #64748b; padding: 6px 0;">No available offers for this amount.</div>';
        }

        var unavailEl = byId('coUnavailableOffersList');
        if (unavailEl) {
            unavailEl.innerHTML = brandUnavailable.length
                ? brandUnavailable.map(renderUnavailableOffer).join('')
                : '<div style="font-size: 12px; color: #64748b; padding: 6px 0;">All brand offers unlocked!</div>';
        }

        var paymentEl = byId('coPaymentOffersList');
        if (paymentEl) {
            paymentEl.innerHTML = paymentOffers.length
                ? paymentOffers.map(function(item) {
                    return item.eligible ? renderAvailableOffer(item, appliedCode) : renderUnavailableOffer(item);
                }).join('')
                : '<div style="font-size: 12px; color: #64748b; padding: 6px 0;">No payment offers available right now.</div>';
        }
    }

    function renderSlideOffers() {
        var totals = currentDrawerTotals();
        setText('coOffersCartCount', totals.count);

        var loading = '<div style="font-size: 12px; color: #64748b; padding: 6px 0;">Loading offers...</div>';
        ['coAvailableOffersList', 'coUnavailableOffersList', 'coPaymentOffersList'].forEach(function(id) {
            var el = byId(id);
            if (el) el.innerHTML = loading;
        });

        fetch(cfg.availableCouponsUrl || '/coupon/available', {
            headers: { 'Accept': 'application/json' }
        })
        .then(function(r){ return r.json(); })
        .then(function(data){
            if (!data || !data.success) throw new Error('Offers unavailable');
            renderSlideOfferData(
                data.coupons || [],
                Number(data.subtotal || totals.subtotal),
                Number(data.cart_count || totals.count),
                data.applied_code || ''
            );
        })
        .catch(function() {
            renderSlideOfferData(cfg.allCoupons || [], totals.subtotal, totals.count, '');
        });
    }

    w.applySpecificCoupon = function(code) {
        fetch('/coupon/apply', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': csrfToken(), 'Accept': 'application/json' },
            body: JSON.stringify({ code: code })
        })
        .then(function(r){ return r.json(); })
        .then(function(res){
            if (res.success) {
                var disc = Number(res.discount || 0);
                if (typeof w.showCouponPartyPopup === 'function') {
                    w.showCouponPartyPopup({
                        code: code,
                        discount: disc,
                        message: res.message || ('Coupon ' + code + ' applied successfully!')
                    });
                } else if (typeof w.tttNotify === 'function') {
                    w.tttNotify(res.message || ('Coupon ' + code + ' applied!'), 'success');
                }
                if (lastCart) {
                    lastCart.discount = disc;
                    recalcDrawerCart();
                }
                w.switchToSlideCartView();
            } else {
                if (typeof w.tttNotify === 'function') w.tttNotify(res.message || 'Could not apply coupon.', 'error');
            }
        })
        .catch(function(){
            if (typeof w.tttNotify === 'function') w.tttNotify('Could not apply coupon.', 'error');
        });
    };

    w.applySlideCouponFromOffers = function() {
        var inp = byId('offersDrawerCouponInput');
        if (!inp || !inp.value.trim()) {
            if (typeof w.tttNotify === 'function') w.tttNotify('Please enter a coupon code.', 'error');
            return;
        }
        w.applySpecificCoupon(inp.value.trim().toUpperCase());
    };

    w.applySlideCoupon = function() {
        var inp = byId('slideDrawerCouponInput');
        if (!inp || !inp.value.trim()) {
            if (typeof w.tttNotify === 'function') w.tttNotify('Please enter a coupon code.', 'error');
            return;
        }
        var code = inp.value.trim().toUpperCase();
        w.applySpecificCoupon(code);
    };

    w.quickAddRelated = function(id) {
        if (typeof w.openSlider === 'function') {
            w.openSlider(id);
            return;
        }

        if (typeof w.tttNotify === 'function') {
            w.tttNotify('Please open product details and select Front or Back print side.', 'error');
        }
        return;
    };

    function recalcDrawerCart() {
        if (!lastCart) return;
        var subtotal = (lastCart.items || []).reduce(function (sum, item) {
            return sum + Number(item.price || 0) * Number(item.quantity || 1);
        }, 0);
        lastCart.subtotal = subtotal;
        lastCart.count = (lastCart.items || []).reduce(function (sum, item) { return sum + Number(item.quantity || 1); }, 0);
        lastCart.shipping = subtotal >= 999 ? 0 : 50;
        lastCart.total = subtotal + lastCart.shipping - Number(lastCart.discount || 0);
        openCheckoutPop(lastCart);
    }

    function renderTotalBreakdown(cart) {
        var subtotal = Number(cart.subtotal || 0);
        var shipping = Number(cart.shipping || 0);
        var savings = Number(cart.savings || cart.discount || 0);
        var prepaid = Math.round(subtotal * 0.05 * 100) / 100;
        var mrp = subtotal + savings;
        var estimated = Math.max(0, subtotal + shipping - prepaid);
        setText('coBreakSaved', money(savings) + ' saved so far');
        setText('coMrpTotal', money(mrp));
        setText('coMrpDiscount', money(savings));
        setText('coCartSubtotal', money(subtotal));
        setText('coTotalDiscount', money(0));
        setText('coPrepaidDiscount', money(prepaid));
        setText('coBreakShipping', shipping === 0 ? 'FREE' : money(shipping));
        setText('coTotalSavings', money(savings + prepaid));
        setText('coBreakTotal', money(estimated));
    }

    function toggleTotalBreakdown() {
        var panel = byId('coTotalBreakdown');
        var icon = byId('coTotalChevron');
        if (!panel) return;
        panel.hidden = !panel.hidden;
        if (icon) {
            icon.classList.toggle('bi-chevron-up', !panel.hidden);
            icon.classList.toggle('bi-chevron-down', panel.hidden);
        }
    }

    function changeDrawerQty(index, delta) {
        if (!lastCart || !lastCart.items || !lastCart.items[index]) return;
        var item = lastCart.items[index];
        item.quantity = Math.max(1, Math.min(99, Number(item.quantity || 1) + Number(delta || 0)));
        if (item.key && cfg.cartUpdateBaseUrl) {
            fetch(cfg.cartUpdateBaseUrl + '/' + encodeURIComponent(item.key), {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': csrfToken(), 'Accept': 'application/json' },
                body: JSON.stringify({ quantity: item.quantity })
            }).catch(function () {});
        }
        recalcDrawerCart();
    }

    function changeDrawerSize(index, size) {
        if (!lastCart || !lastCart.items || !lastCart.items[index]) return;
        var item = lastCart.items[index];
        item.size = size;
        var variant = VARIANTS.find(function (v) {
            return v.size === size && (!item.color || v.color === item.color);
        });
        if (variant && variant.price) {
            item.price = Number(variant.price);
            item.original_price = Number(variant.original_price || item.price);
        }
        recalcDrawerCart();
    }

    function escapeHtml(value) {
        return String(value || '').replace(/[&<>"']/g, function (m) {
            return ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' })[m];
        });
    }

    function toggleCheckoutSection(name) {
        if (name !== 'order') return;
        var el = byId('coOrderItems');
        if (!el) return;
        if (!lastCart) renderOrderItems(fallbackCart());
        el.hidden = !el.hidden;
    }

    function isAddressComplete(user) {
        if (!user) return false;
        var phone = String(user.phone || '').trim();
        var addr = String(user.address || '').trim();
        var pin = String(user.pincode || '').trim();
        var city = String(user.city || '').trim();
        var state = String(user.state || '').trim();
        return phone.length >= 10 && addr.length >= 4 && pin.length >= 4 && city.length >= 2 && state.length >= 2;
    }

    function showAddressEditor() {
        var pop = byId('checkoutPop');
        var form = byId('coAddressForm');
        var fields = byId('coAddressFields');
        if (pop) pop.classList.add('address-mode');
        if (form) form.hidden = false;
        if (fields) fields.hidden = false;
        setText('coAddressMsg', '');
    }

    function showCheckoutMain() {
        var pop = byId('checkoutPop');
        var form = byId('coAddressForm');
        if (pop) pop.classList.remove('address-mode');
        if (form) form.hidden = true;
    }

    function updateAddressPreview(user) {
        user = user || {};
        var name = d.querySelector('.checkout-address-copy .checkout-card-title');
        var lines = d.querySelectorAll('.checkout-address-copy p');
        if (name) name.textContent = 'Deliver To ' + (user.name || 'Customer');
        if (lines[0]) lines[0].textContent = user.address || 'Add your delivery address at checkout';
        if (lines[1]) {
            var contact = [user.phone || '', user.email || ''].filter(Boolean).join(' | ');
            lines[1].textContent = contact;
        }
    }

    function unlockAddressFields() {
        var fields = byId('coAddressFields');
        if (fields) fields.hidden = false;
        var msg = byId('coAddressMsg');
        if (msg) msg.textContent = '';
    }

    function saveCheckoutAddress() {
        var msg = byId('coAddressMsg');
        var payload = {
            name: (byId('coName') || {}).value || (cfg.user || {}).name || 'Customer',
            phone: (byId('coPhone') || {}).value || (cfg.user || {}).phone || '',
            address: (byId('coAddress') || {}).value || (cfg.user || {}).address || '',
            city: (byId('coCity') || {}).value || (cfg.user || {}).city || '',
            state: (byId('coState') || {}).value || (cfg.user || {}).state || '',
            pincode: (byId('coPin') || {}).value || (cfg.user || {}).pincode || ''
        };

        if (!payload.phone || payload.phone.length < 10) {
            if (msg) { msg.textContent = 'Please enter valid 10-digit mobile number.'; msg.style.color = '#dc2626'; }
            byId('coPhone')?.focus();
            return;
        }
        if (!payload.address || payload.address.length < 5) {
            if (msg) { msg.textContent = 'Please enter complete street address.'; msg.style.color = '#dc2626'; }
            byId('coAddress')?.focus();
            return;
        }
        if (!payload.pincode || payload.pincode.length < 5) {
            if (msg) { msg.textContent = 'Please enter valid 6-digit pincode.'; msg.style.color = '#dc2626'; }
            byId('coPin')?.focus();
            return;
        }
        if (!payload.city || !payload.state) {
            if (msg) { msg.textContent = 'City and State are required.'; msg.style.color = '#dc2626'; }
            return;
        }

        if (msg) {
            msg.textContent = 'Saving address & connecting to Razorpay...';
            msg.style.color = '#047857';
        }

        cfg.user = Object.assign({}, cfg.user || {}, payload);
        updateAddressPreview(cfg.user);

        if (cfg.addressUpdateUrl) {
            fetch(cfg.addressUpdateUrl, {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': csrfToken(), 'Accept': 'application/json' },
                body: JSON.stringify(payload)
            }).then(function (r) { return r.json(); })
                .then(function (res) {
                    if (res.user) cfg.user = Object.assign({}, cfg.user, res.user);
                    updateAddressPreview(cfg.user);
                    closeCheckoutPop();
                    openRazorpay(lastCart || fallbackCart());
                }).catch(function () {
                    closeCheckoutPop();
                    openRazorpay(lastCart || fallbackCart());
                });
        } else {
            closeCheckoutPop();
            openRazorpay(lastCart || fallbackCart());
        }
    }

    function buyNow() {
        if (!selectedDesignSide) {
            var sideBox = byId('designSideBox');
            var sideMsg = byId('designSideMsg');
            if (sideBox) {
                sideBox.classList.remove('needs-choice');
                void sideBox.offsetWidth;
                sideBox.classList.add('needs-choice');
                sideBox.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
            if (sideMsg) {
                sideMsg.style.display = 'block';
                sideMsg.textContent = '⚠️ Please select Front Side or Back Side print first!';
            }
            var buyBtn = byId('buyBtn');
            if (buyBtn) {
                var oldText = buyBtn.textContent;
                buyBtn.textContent = 'SELECT PRINT SIDE!';
                buyBtn.style.background = '#dc2626';
                buyBtn.style.color = '#ffffff';
                setTimeout(function () {
                    buyBtn.style.background = '';
                    buyBtn.style.color = '';
                    buyBtn.textContent = oldText;
                }, 1800);
            }
            showToast('Please select Front Side or Back Side print.');
            return;
        }

        if (window.TTT_IS_AUTHENTICATED === false) {
            if (w.TTT_AUTH_MODAL && typeof w.TTT_AUTH_MODAL.open === 'function') {
                w.TTT_AUTH_MODAL.open(function () {
                    window.TTT_IS_AUTHENTICATED = true;
                    buyNow();
                });
                return;
            }
        }
        addToCart(false, 'buyBtn', function (res) {
            var cart = res && res.cart ? res.cart : fallbackCart();
            if (typeof window.openGlobalCheckoutModal === 'function') {
                var p = cfg.drawerProduct || {};
                var fallbackProduct = {
                    id: cfg.productId,
                    name: p.name || 'Product',
                    image: p.image || '',
                    size: selectedSize || 'Regular',
                    design_side: selectedDesignSide,
                    quantity: selectedQty,
                    price: Number(p.price || cfg.basePrice || 0),
                    original_price: Number(p.original_price || p.price || cfg.basePrice || 0)
                };
                window.openGlobalCheckoutModal(cart, fallbackProduct);
            } else {
                openCheckoutPop(cart);
            }
        });
    }

    function openRazorpay(cart) {
        cart = cart || fallbackCart();
        var cfg = window.TTT_PRODUCT_SHOW || {};
        var subtotal = Number(cart.subtotal || 0);
        var shipping = Number(cart.shipping || (subtotal >= 999 ? 0 : 50));
        var discount = Number(cart.discount || 0);
        var total    = Number(cart.total || Math.max(0, subtotal + shipping - discount));

        // Show loading overlay
        var overlay = byId('rzpLoadingPop');
        if (overlay) { overlay.classList.add('is-open'); overlay.setAttribute('aria-hidden', 'false'); }
        d.body.style.overflow = 'hidden';

        fetch(cfg.razorpayCreateUrl, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-CSRF-TOKEN': csrfToken(),
                'Accept': 'application/json',
            },
            body: JSON.stringify({ amount: total, product_id: cfg.productId }),
        })
        .then(function (r) { return r.json(); })
        .then(function (data) {
            if (overlay) { overlay.classList.remove('is-open'); overlay.setAttribute('aria-hidden', 'true'); }
            d.body.style.overflow = '';

            if (!data.success) {
                showToast(data.message || 'Payment initiation failed.');
                return;
            }

            var user = cfg.user || {};
            var options = {
                key: data.key,
                amount: data.amount,
                currency: data.currency,
                order_id: data.razorpay_order_id,
                name: 'Vayu',
                description: 'Fashion Order',
                image: '/favicon.ico',
                prefill: {
                    name: user.name || '',
                    email: user.email || '',
                    contact: user.phone || '',
                },
                theme: { color: '#00285a' },
                handler: function (response) {
                    // Verify payment on server
                    fetch(cfg.razorpayVerifyUrl, {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                            'X-CSRF-TOKEN': csrfToken(),
                            'Accept': 'application/json',
                        },
                        body: JSON.stringify({
                            razorpay_order_id:   response.razorpay_order_id,
                            razorpay_payment_id: response.razorpay_payment_id,
                            razorpay_signature:  response.razorpay_signature,
                            order_data: {
                                product_id: cfg.productId,
                                name:       user.name    || '',
                                email:      user.email   || '',
                                phone:      user.phone   || '',
                                address:    user.address || '',
                                city:       user.city    || '',
                                state:      user.state   || '',
                                pincode:    user.pincode || '',
                                subtotal:   subtotal,
                                shipping:   shipping,
                                total:      total,
                                qty:        1,
                            },
                        }),
                    })
                    .then(function (r) { return r.json(); })
                    .then(function (res) {
                        if (res.success && res.redirect) {
                            w.location.href = res.redirect;
                        } else {
                            showToast(res.message || 'Payment verification failed.');
                        }
                    })
                    .catch(function () { showToast('Verification error. Contact support.'); });
                },
                modal: {
                    ondismiss: function () {
                        d.body.style.overflow = '';
                        showToast('Payment cancelled.');
                    },
                },
            };

            var rzp = new Razorpay(options);
            rzp.on('payment.failed', function (response) {
                showToast('Payment failed: ' + (response.error.description || 'Unknown error'));
                fetch(cfg.razorpayFailureUrl, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': csrfToken() },
                    body: JSON.stringify({ error: response.error.description }),
                });
            });
            rzp.open();
        })
        .catch(function () {
            if (overlay) { overlay.classList.remove('is-open'); overlay.setAttribute('aria-hidden', 'true'); }
            d.body.style.overflow = '';
            showToast('Could not connect to payment server. Please try again.');
        });
    }

    function showToast(msg) {
        var t = byId('toast');
        if (!t) return;
        t.textContent = msg;
        t.classList.add('show');
        setTimeout(function () { t.classList.remove('show'); }, 2500);
    }

    function syncFromUrl() {
        var color = getColorFromUrl() || selectedColor;
        var el = findColorItem(color);
        if (el) selectColor(el.getAttribute('data-color'), el.getAttribute('data-hex') || '', el, true);
        else if (selectedColor) updateSizesForColor(selectedColor);

        var initialSizeBtn = qsa('.size-btn.active')[0] || qsa('.size-btn:not(.oos):not([disabled])')[0];
        if (initialSizeBtn) {
            selectSize(initialSizeBtn);
        }
    }

    syncFromUrl();
    if (selectedDesignSide) {
        selectDesignSide(selectedDesignSide);
    }
    w.addEventListener('popstate', syncFromUrl);
    w.addEventListener('keydown', function (e) {
        if (e.key === 'Escape') {
            closeCheckoutPop();
            closeProductGallery();
        }
    });

    w.switchImg = switchImg;
    w.openProductGallery = openProductGallery;
    w.closeProductGallery = closeProductGallery;
    w.moveProductGallery = moveProductGallery;
    w.showProductGalleryImage = showProductGalleryImage;
    w.selectColor = selectColor;
    w.selectSize = selectSize;
    w.selectDesignSide = selectDesignSide;
    w.addToCart = function () { addToCart(true, 'atcBtn'); };
    w.changeQty = changeQty;
    w.buyNow = buyNow;
    w.openRazorpay = openRazorpay;
    w.closeCheckoutPop = closeCheckoutPop;
    w.openCheckoutPop = openCheckoutPop;
    w.changeDrawerQty = changeDrawerQty;
    w.changeDrawerSize = changeDrawerSize;
    w.toggleTotalBreakdown = toggleTotalBreakdown;
    w.toggleCheckoutSection = toggleCheckoutSection;
    w.showAddressEditor = showAddressEditor;
    w.showCheckoutMain = showCheckoutMain;
    w.unlockAddressFields = unlockAddressFields;
    w.saveCheckoutAddress = saveCheckoutAddress;
    w.showToast = showToast;
})(window, document);
